<script setup lang="ts">import {fixed} from '../utils/format';defineProps<{rows:any[],selected?:string}>();defineEmits<{select:[id:string]}>()</script><template><section class="information-ranking"><h2>候选观测 / 期望信息增益</h2><p class="empty" v-if="!rows.length">没有未观测的非目标候选；后验与证据概率仍完整保留。</p><button v-for="r in rows" :key="r.node_id" :class="['candidate-button',{active:r.node_id===selected}]" @click="$emit('select',r.node_id)"><span><b>{{r.node_id}}</b><small>期望熵 {{fixed(r.expected_entropy,6)}} bit</small></span><strong>{{fixed(r.information_gain,6)}} <em>bit</em></strong></button><p class="method-note">IG = H(Q|E) − ΣP(X|E)H(Q|E,X)。排序只在给定模型内解释，不输出真实检查或维修建议。</p></section></template>
